function reorderList(head) {
  // 1. find the middle
  let slow = head, fast = head;
  while (fast.next !== null && fast.next.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
  }
  // 2. reverse the second half
  let prev = null, curr = slow.next;
  slow.next = null;              // cut the list in two
  while (curr !== null) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  // 3. weave the halves together
  let first = head, second = prev;
  while (second !== null) {
    const next1 = first.next, next2 = second.next;
    first.next = second;
    second.next = next1;
    first = next1;
    second = next2;
  }
}

